head.script:
scwin.onpageload = function () {
    scwin.userId = $p.getParameter("userId");
    scwin.userName = $p.getParameter("userName");
    scwin.userImage = $p.getParameter("userImage");
    console.log(scwin.userId);
    console.log(scwin.userName);
    console.log(scwin.userImage);
};

scwin.new_task_onclick = function (e) {
    //팝업 호출
    //팝업 화면에 데이터를 전달 (dataObject를 통해 전달 가능)
    var param = {
        "type": "json", // 데이터 유형. "json"을 권장
        "name": "userInfo",  // 데이터를 가져오기 위한 파라미터 이름으로 팝업 화면에서 $p.getParameter("exam_param")로 추출할 수 있음
        "data": {
            "userId": scwin.userId,
            "userName": scwin.userName,
            "userImage": scwin.userImage
        } // 실제 전달할 데이터
    };

    // 팝업 생성 옵션 지정
    var options = {
        id: "exa_popup",
        type: "wframePopup",
        width: "1300",
        height: "750",
        top: "140",
        left: "350",
        popupName: "2차프로젝트 / 진행중",
        modal: false,
        closeAction: "scwin.popup_closeAction",
        customTitleBar: false,
        dataObject: param
    };

    // 팝업 생성
    $p.openPopup("./taskModal.xml", options);

};
// 팝업 생성 옵션의 closeAction 함수 정의 예시
scwin.popup_closeAction = function (argRuntimeID, argJsnInfo) {
    var popObj = $p.getPopupWindow(argRuntimeID);
    return true; //팝업 닫기 (반환 값이 true인 경우만 팝업이 닫힘)
};
